cases.questionText:
假设曲面$S \mathpunct{:}\br=\br(u,v)$的单位法向量为$\bn$. 定义曲面$\tilde S \mathpunct{:}\tilde\br(u,v)=\br(u,v)+\lambda\bn(u,v)$为曲面$S$的\emph{平行曲面}, 其中$\lambda$为常数. 试证明:
  \begin{enumerate}
    \item 当$\lambda$充分小时, $\tilde S$是正则曲面;
    \item 如果$S$的Gauss曲率为$K$, 平均曲率为$H$, 那么$\tilde S$的高斯曲率为
      \[
        \tilde K=\frac{K}{1-2\lambda H+\lambda^2K}.
      \]
  \end{enumerate}

cases.correctAnswer:
直接计算知道
    \[
      \tilde\br_u=\br_u+\lambda\bn_u,\quad \tilde\br_v=\br_v+\lambda\bn_v.
    \]
    则
    \[
      \begin{pmatrix}
        -\bn_u\\
        -\bn_v
      \end{pmatrix}=W
      \begin{pmatrix}
        \br_u\\
        \br_v
      \end{pmatrix}
      \implies
     \begin{pmatrix}
        \tilde\br_u\\
        \tilde\br_v
      \end{pmatrix}=(\lambda E-W)
      \begin{pmatrix}
        \br_u\\
        \br_v
      \end{pmatrix}.\score{2}
    \]
\begin{enumerate}
  \item 为了证明$\tilde S$为正则参数曲面, 只需验证
    \[
      \tilde\br_u\wedge\tilde\br_v\neq0.\score{2}
    \]
    注意到
    \begin{equation}\label{eq:normal}
      \tilde\br_u\wedge\tilde\br_v=\det\left(  E-\lambda W \right)\br_u\wedge\br_v.
    \end{equation}
    因为当$\lambda$充分小时, $A \mathpunct{:}= E-\lambda W$仍是正定矩阵. 我们知道此时$\det A=\det (E-\lambda W)>0$, 可见此时$\tilde S$为正则曲面.\score{3}
  \item 为了计算Gauss曲率, 我们只需求出曲面$\tilde S$的Weingarten变换. 假设$\tilde S$的法向量为$\tilde \bn$, 则从\eqref{eq:normal}知道$\tilde\bn=\bn$, 且
    \[
      \begin{pmatrix}
        -\tilde\bn_u\\
        -\tilde\bn_v
      \end{pmatrix}=
      \begin{pmatrix}
        -\bn_u\\
        -\bn_v
      \end{pmatrix}= W
      \begin{pmatrix}
        \br_u\\
        \br_v
      \end{pmatrix}=WA^{-1}
      \begin{pmatrix}
        \tilde\br_u\\
        \tilde\br_v
      \end{pmatrix}.
    \]
    可见$\tilde S$在自然基底下的Weingarten变换矩阵为$\tilde W=WA^{-1}$. 
    从而
    \[
      \tilde K=\det\tilde W=\det W/\det A=K/\det A.\score{3}
    \]
    最后, 若设$W$的两个特征值为$\kappa_1,\kappa_2$, 则$K=\kappa_1\kappa_2$, $2H=\kappa_1+\kappa_2$. 并且存在可逆矩阵$P$, 使得
    \[
      P^{-1}WP=\Lambda =\mathpunct{:}\mathrm{diag}(\kappa_1,\kappa_2).
    \]
    因此
    \begin{align*}
      \det A&=\det\left(  E-\lambda P\Lambda P^{-1} \right)=\det\left( P( E-\lambda\Lambda)P^{-1} \right)=\det( E-\lambda\Lambda)\\
            &=(1-\lambda \kappa_1)(1-\lambda\kappa_2)=1-2H\lambda+\lambda^2K,
    \end{align*}
    由此易见结论成立.\score{5}
\end{enumerate}

